function modal(title,body,handler){$('#modal-body').innerHTML=`<h2>${esc(title)}</h2><form id="modal-form">${body}<button class="wide actions" type="submit">保存</button></form>`;$('#modal-form').addEventListener('submit',e=>{e.preventDefault();try{handler(new FormData(e.target));if(save()){closeModal();render();toast('已保存');}else{closeModal();render();}}catch(err){toast(err.message);}});openModal();}
function weightTrendPanel(){const trend=weightTrend(state,selected,weightRange);return `<section class="card" id="weight-trends"><div class="section-head"><h2>体重趋势</h2><div class="stack"><button class="tiny ${weightRange===7?'':'secondary'}" data-action="weight-range" data-id="7" aria-pressed="${weightRange===7}">7 天</button><button class="tiny ${weightRange===30?'':'secondary'}" data-action="weight-range" data-id="30" aria-pressed="${weightRange===30}">30 天</button></div></div><div class="weight-summary"><div><small>最近一次实测</small><b>${trend.latest?`${trend.latest.weight.toFixed(1)} kg`:'未记录'}</b><small>${esc(trend.latest?.date??'')}</small></div><div><small>所选区间实测变化</small><b>${trend.change==null?'—':`${trend.change>0?'+':''}${trend.change.toFixed(1)} kg`}</b><small>${trend.recordedCount} 次记录</small></div></div>${renderWeightChart(trend)}${trend.advice.map(item=>`<p class="muted">${esc(item.text)}</p>`).join('')}<p class="muted">实线为实测，虚线为 7 日记录均值；窗口内至少有 3 次记录才显示均值。缺失日期留空，趋势不会自动改变饮食目标。</p><button class="secondary tiny actions" data-action="quick-weight">记录 ${esc(selected)} 的体重</button></section>`;}
function mondayOf(key){const weekday=new Date(`${key}T12:00:00`).getDay();return offsetDate(key,-((weekday+6)%7));}
function weeklyCard(){const monday=mondayOf(selected);return `<section class="card" id="weekly-planner"><div class="section-head"><div><h2>本周 · ${esc(monday.slice(5))} — ${esc(offsetDate(monday,6).slice(5))}</h2><small>每个动作单独勾选；可以提前查看未来安排。</small></div><button data-action="import-week">导入整周计划</button></div><div class="week-days">${Array.from({length:7},(_,i)=>{const date=offsetDate(monday,i),stored=state.days[date],tasks=stored?.tasks??state.plans.filter(p=>p.weekdays.includes((i+1)%7)&&(!p.startDate||date>=p.startDate)),done=tasks.filter(t=>t.status==='done').length;return `<button class="week-day ${selected===date?'active':''}" data-action="week-day" data-id="${date}" aria-pressed="${selected===date}"><span>周${'一二三四五六日'[i]}</span><b>${date.slice(8)}</b><small>${done}/${tasks.length}项</small></button>`;}).join('')}</div><div class="stack actions"><button class="secondary tiny" data-action="week-prev">上一周</button><button class="secondary tiny" data-action="week-today">回到今天</button><button class="secondary tiny" data-action="week-next">下一周</button></div></section>`;}
let weeklyDraft={text:'',startDate:null,repeat:true,items:[]};
function weeklyEditor(text=weeklyDraft.text,startDate=weeklyDraft.startDate??mondayOf(dateKey()),repeat=weeklyDraft.repeat){weeklyDraft={text,startDate,repeat,items:[]};$('#modal-body').innerHTML=`<h2>一次导入一周计划</h2><p class="muted">从聊天或备忘录复制整周文字，每天写“周一、周二……”；每个动作独立一行。先预览，再导入，不需要逐个创建。格式示例只演示写法，请换成你的实际计划。</p><form id="weekly-text-form"><label for="weekly-text">粘贴整周计划</label><textarea id="weekly-text" name="text" rows="9" maxlength="20000" required placeholder="周一&#10;深蹲 3组×12次&#10;快走 20分钟&#10;周二&#10;休息">${esc(text)}</textarea><button type="button" class="secondary tiny actions" data-action="week-example">填入格式示例</button><label for="week-start">从哪一周开始（选择周一）</label><input type="date" id="week-start" name="startDate" value="${esc(startDate)}" required><div class="inline-check"><input type="checkbox" id="week-repeat" name="repeat" ${repeat?'checked':''}><label for="week-repeat">以后每周重复这套计划</label></div><p class="muted">取消重复则只安排所选一周。早于今天的日期不会补写；已有项目和打卡会保留，同名同安排不重复添加。每周重复也会补齐已提前查看过的未来日期。未写时间默认 18:30。</p><button class="wide actions" type="submit">预览，检查每天项目</button><p class="sync-error" id="weekly-error" role="status"></p></form>`;if(!$('#modal').hasAttribute('open'))openModal();}
function weeklyReview(parsed){weeklyDraft.items=parsed.items;$('#modal-body').innerHTML=`<h2>确认一周计划</h2><p class="muted">${esc(weeklyDraft.startDate)} 起 · ${weeklyDraft.repeat?'每周重复':'仅这一周'}。取消勾选的项目不会导入。</p>${parsed.warnings.map(w=>`<p class="note">${esc(w)}</p>`).join('')}<form id="weekly-review-form"><div id="weekly-preview">${parsed.items.map((t,i)=>`<label class="weekly-preview-item"><input type="checkbox" name="item" value="${i}" checked><span><b>周${t.weekdays.map(v=>'日一二三四五六'[v]).join('、')} · ${esc(t.name)}</b><small>${esc(t.category)} · ${esc(t.time)}${t.minutes?` · ${t.minutes}分钟`:''}</small>${t.instructions?`<small>${esc(t.instructions)}</small>`:''}</span></label>`).join('')}</div><p class="muted">这是文字解析结果，请核对动作、星期和组次。只追加今天及以后的项目。每周重复也会补齐已提前查看过的未来日期；仅一次则只安排所选周。保留已完成勾选、饮食和历史记录。</p><button class="wide actions" type="submit">确认导入选中项目</button><button class="secondary wide" type="button" data-action="week-edit">返回修改文字</button><p class="sync-error" id="weekly-error" role="status"></p></form>`;}
document.addEventListener('submit',e=>{
  if(e.target.id==='weekly-text-form'){
    e.preventDefault();const f=new FormData(e.target);weeklyDraft={text:f.get('text').trim(),startDate:f.get('startDate'),repeat:f.has('repeat'),items:[]};
    if(!/^\d{4}-\d{2}-\d{2}$/.test(weeklyDraft.startDate)||new Date(`${weeklyDraft.startDate}T12:00:00`).getDay()!==1){$('#weekly-error').textContent='请选择有效的周一日期。';return;}
    const parsed=parseWeeklyPlan(weeklyDraft.text);if(parsed.errors.length){$('#weekly-error').textContent=parsed.errors.join('；');return;}if(!parsed.items.length){$('#weekly-error').textContent='没有找到可导入的项目，请按星期分别写出动作。';return;}weeklyReview(parsed);
  }
  if(e.target.id==='weekly-review-form'){
    e.preventDefault();const f=new FormData(e.target),items=f.getAll('item').map(i=>weeklyDraft.items[Number(i)]);if(!items.length){$('#weekly-error').textContent='请至少选择一个项目。';return;}
    try{const result=applyWeeklyPlan(state,items,{startDate:weeklyDraft.startDate,repeat:weeklyDraft.repeat,today:dateKey()});if(save()){selected=dateKey()>offsetDate(weeklyDraft.startDate,6)?dateKey():dateKey()<weeklyDraft.startDate?weeklyDraft.startDate:dateKey();weeklyDraft={text:'',startDate:null,repeat:true,items:[]};closeModal();if(tab!=='training')location.hash='training';else render();toast(`已添加 ${result.added} 项安排${result.duplicates?`，跳过 ${result.duplicates} 项重复`:''}`);}else{$('#weekly-error').textContent='保存失败，本次导入已撤销，可重试。';}}catch(error){$('#weekly-error').textContent=error.message;}
  }
});
document.addEventListener('input',e=>{if(e.target.id==='weekly-text')weeklyDraft.text=e.target.value;});
let speechDraft={text:'',noteId:null,date:null,parsed:null},speechRequestId=null;
function speechEditor(text='',noteId=null,date=selected){speechDraft={text,noteId,date,parsed:null};$('#modal-body').innerHTML=`<h2>说一句，记一餐</h2><p class="muted">保存到 ${esc(date)}。可以使用系统语音或输入法麦克风；这里只匹配你的常吃食物，不猜菜品热量。</p><form id="speech-text-form"><label for="mealSpeechText">饮食描述</label><textarea id="mealSpeechText" name="text" maxlength="2000" required placeholder="午餐鸡胸肉150克，米饭200克">${esc(text)}</textarea><div class="stack actions"><button type="button" class="secondary" data-action="voice-meal">🎙 再说一次</button><button type="submit">识别食物与份量</button><button type="button" class="secondary" data-action="save-food-note">仅保存待补全备注</button></div></form>`;if(!$('#modal').hasAttribute('open'))openModal();}
function speechReview(text){const parsed=parseMealSpeech(text,state.foods);speechDraft={...speechDraft,text,parsed};$('#modal-body').innerHTML=`<h2>确认这一餐</h2><p class="muted">${esc(text)}</p><form id="speech-review-form"><label for="speechMeal">餐次</label><select id="speechMeal" name="meal">${['早餐','午餐','晚餐','加餐'].map(m=>`<option ${m===parsed.meal?'selected':''}>${m}</option>`).join('')}</select>${parsed.items.map((item,i)=>`<label for="speech-grams-${i}">${esc(item.name)} · 实际克数</label><input id="speech-grams-${i}" name="grams-${i}" type="number" min="0.1" max="10000" step="0.1" required value="${item.grams??''}" placeholder="${esc(item.issue??'请确认')}">`).join('')}${parsed.unmatched?`<div class="note actions">未匹配：${esc(parsed.unmatched)}。请先创建对应常吃食物；可以先保存备注，之后补录。</div>`:''}${!parsed.items.length?'<p class="muted">未匹配你的常吃食物。先保存备注即可，热量暂不计算。</p>':''}<button type="submit" class="wide actions" ${!parsed.items.length||parsed.unmatched?'disabled':''}>确认并记录 ${parsed.items.length} 项</button><div class="stack actions"><button type="button" class="secondary" data-action="edit-speech">修改描述</button><button type="button" class="secondary" data-action="save-food-note">保存待补全备注</button></div></form>`;}
function storeFoodNote(){const text=($('#mealSpeechText')?.value??speechDraft.text).trim();if(!text){toast('请先输入饮食描述');return;}const day=ensureDay(state,speechDraft.date??selected),existing=day.foodNotes.find(n=>n.id===speechDraft.noteId);if(existing)existing.text=text;else day.foodNotes.push({id:uid(),text,createdAt:new Date().toISOString()});day.foodComplete=false;if(save()){toast('已保存待补全备注，尚未计算热量');}closeModal();render();}
function requestSpeech(){
  if(speechBusy){toast('正在等待系统语音结果');return;}
  const text=$('#mealSpeechText')?.value??'',date=$('#modal').hasAttribute('open')?speechDraft.date:selected,noteId=$('#modal').hasAttribute('open')?speechDraft.noteId:null;
  speechEditor(text,noteId,date);
  if(!native?.requestSpeech){toast('浏览器预览请使用输入法麦克风；安装版可调用手机系统语音');return;}
  speechBusy=true;speechRequestId=uid();native.requestSpeech(speechRequestId);
}
globalThis.nativeSpeechResult=(id,ok,payload)=>{if(id!==speechRequestId)return;speechBusy=false;speechRequestId=null;if(ok&&payload.text){speechEditor(payload.text,speechDraft.noteId,speechDraft.date);speechReview(payload.text);}else if(payload.code!=='cancelled')toast(payload.error??'语音服务不可用，可用输入法麦克风或手动输入');};
const healthPending=new Map();
globalThis.nativeHealthResult=(id,ok,payload)=>{const p=healthPending.get(id);if(!p)return;healthPending.delete(id);clearTimeout(p.timeout);ok?p.resolve(payload):p.reject(Error(payload.error??payload.message??'读取失败，请检查系统支持与权限'));};
async function syncHealth(){if(!SYNC_ENABLED){toast('本版已暂停数据同步');return;}if(healthBusy)return;if(!native?.healthSnapshot){toast('这个入口需要支持 Health Connect 的安卓安装版；华为可使用 WHOOP 官方云连接');return;}healthBusy=true;render();try{const payload=await new Promise((resolve,reject)=>{const id=uid(),timeout=setTimeout(()=>{healthPending.delete(id);reject(Error('健康数据读取超时，请稍后重试'));},45000);healthPending.set(id,{resolve,reject,timeout});native.healthSnapshot(id);});state.healthConnect=normalizeHealthConnect(payload);healthSyncError=null;if(save())toast(state.healthConnect.records.length?'已读取手机中的 WHOOP 记录':'读取成功，尚无 WHOOP 来源记录，请先在 WHOOP 开启健康共享');}catch(e){healthSyncError=e.message;toast(e.message);}finally{healthBusy=false;render();}}
const weekdays=`<label>每周重复</label><div class="day-pills">${[1,2,3,4,5,6,0].map(d=>`<label><input type="checkbox" name="weekday" value="${d}">周${'日一二三四五六'[d]}</label>`).join('')}</div>`;
function taskForm(plan=false,existing=null){const day=ensureDay(state,selected);modal(plan?'每周训练计划':'添加当天安排',`<label for="taskName">运动名称</label><input id="taskName" name="name" required maxlength="100" placeholder="例如：快走、深蹲、休息日" value="${esc(existing?.name??'')}"><label for="category">分类</label><select id="category" name="category">${['力量','有氧','拉伸','休息'].map(c=>`<option ${existing?.category===c?'selected':''}>${c}</option>`).join('')}</select><div class="fields"><div><label for="taskTime">计划时间</label><input id="taskTime" name="time" type="time" value="${esc(existing?.time??state.settings.trainingTime)}" required></div><div><label for="minutes">计划时长（分钟）</label><input id="minutes" name="minutes" type="number" min="0" max="1440" value="${existing?.minutes??''}" placeholder="可不填"></div></div><label for="instructions">计划说明（组次等，可留空）</label><textarea id="instructions" name="instructions" maxlength="500" placeholder="例如：3组×12次">${esc(existing?.instructions??'')}</textarea>${plan?weekdays:''}`,f=>{const name=f.get('name').trim();if(!name)throw Error('请填写运动名称');const task={...(existing??{}),id:existing?.id??uid(),name,category:f.get('category'),time:f.get('time'),instructions:f.get('instructions').trim(),minutes:num(f,'minutes')??0,weekdays:plan?f.getAll('weekday').map(Number):[]};if(plan){if(!task.weekdays.length)throw Error('至少选择一天');if(existing)state.plans[state.plans.findIndex(p=>p.id===existing.id)]=task;else state.plans.push(task);}else day.tasks.push({...task,status:'pending',sets:[],actualMinutes:null});});if(existing)document.querySelectorAll('[name=weekday]').forEach(c=>c.checked=existing.weekdays.includes(Number(c.value)));}
function foodForm(existing=null){modal(existing?'编辑常吃食物':'创建常吃食物',`<label for="foodName">名称</label><input id="foodName" name="name" required maxlength="100" value="${esc(existing?.name??'')}"><p class="muted">以下均为每 100 g 的数值。修改后不会重算过去的饮食记录。</p><label for="foodCalories">热量（kcal / 100 g）</label><input id="foodCalories" name="calories" type="number" min="0" max="10000" step="0.1" required value="${existing?.calories??''}"><label for="foodProtein">蛋白质（g / 100 g）</label><input id="foodProtein" name="protein" type="number" min="0" max="1000" step="0.1" required value="${existing?.protein??''}"><label for="foodCarbs">碳水（g / 100 g，可留空）</label><input id="foodCarbs" name="carbs" type="number" min="0" max="100" step="0.1" value="${existing?.carbs??''}" placeholder="包装未标注时留空，不猜数值"><label for="portionGrams">快捷记录每份重量（g，可留空）</label><input id="portionGrams" name="portionGrams" type="number" min="0.1" max="10000" step="0.1" value="${existing?.portionGrams??''}" placeholder="例如：常吃的一份为150g">`,f=>{if(!f.get('name').trim())throw Error('请填写名称');const food={id:existing?.id??uid(),name:f.get('name').trim(),calories:num(f,'calories'),protein:num(f,'protein'),carbs:num(f,'carbs'),portionGrams:num(f,'portionGrams')};if(existing)state.foods[state.foods.findIndex(x=>x.id===existing.id)]=food;else state.foods.push(food);});}
async function connectionToken(){return native?native.getPairToken():(sessionStorage.getItem('motion-pair-token')??'');}
async function api(path,method='GET'){const token=await connectionToken(),base=state.settings.serverUrl.replace(/\/$/,'');if(!base||!token)throw Error('请先保存同步服务地址和连接密钥');if(!/^https:\/\//.test(base))throw Error('服务地址需要使用 HTTPS');if(native)return new Promise((resolve,reject)=>{const id=uid();pending.set(id,{resolve,reject});native.api(id,base,path,method);});const res=await fetch(base+path,{method,headers:{Authorization:`Bearer ${token}`},signal:AbortSignal.timeout(20000)});const payload=await res.json();if(!res.ok)throw Error(payload.error??'同步服务暂时不可用');return payload;}
const pending=new Map();globalThis.nativeApiResult=(id,ok,payload)=>{const task=pending.get(id);if(!task)return;pending.delete(id);ok?task.resolve(payload):task.reject(Error(payload.error??'请求失败'));};
async function syncWhoop(quiet=false){if(!SYNC_ENABLED){if(!quiet)toast('本版已暂停数据同步');return;}if(busy)return;if(!quiet&&formDrafts.has('connection-form')){toast('连接信息有未保存修改，请先保存连接');return;}const revision=connectionRevision;busy=true;if(tab==='settings')render();try{const data=normalizeWhoop(await api(`/api/snapshot?timezone=${encodeURIComponent(Intl.DateTimeFormat().resolvedOptions().timeZone)}`));if(revision!==connectionRevision)return;state.whoop=data;whoopSyncError=null;const saved=save();if(saved&&!quiet)toast('已获取 WHOOP 数据');}catch(e){if(revision!==connectionRevision)return;whoopSyncError=e.message;if(!quiet)toast(e.message);}finally{busy=false;render();}}
async function checkWhoop(){if(!SYNC_ENABLED){toast('本版已暂停数据同步');return;}if(whoopChecking)return;if(formDrafts.has('connection-form')){whoopStatus={error:'连接信息有未保存修改，请先点“保存连接”'};render();return;}const revision=connectionRevision;whoopChecking=true;render();try{const result=await api('/api/status');if(revision!==connectionRevision)return;if(result.apiVersion!=='v2'||typeof result.configured!=='boolean'||typeof result.hasToken!=='boolean'||typeof result.message!=='string')throw Error('服务自检响应不完整，请更新同步服务');whoopStatus=result;}catch(e){if(revision===connectionRevision)whoopStatus={error:e.message};}finally{whoopChecking=false;render();}}
async function action(a,id,button){const day=ensureDay(state,selected),t=day.tasks.find(t=>t.id===id);
  if(storageBroken&&!['export','import'].includes(a)){toast('本地数据读取异常，请先导出原始数据或恢复备份');return;}
  if((a.startsWith('whoop-')||a.startsWith('health-'))&&!SYNC_ENABLED){toast('本版已暂停数据同步');return;}
  if(a==='import-week'){weeklyEditor();return;}
  if(a==='week-example'){weeklyEditor(EXAMPLE_WEEK,$('#week-start')?.value??weeklyDraft.startDate,$('#week-repeat')?.checked??weeklyDraft.repeat);return;}
  if(a==='week-edit'){weeklyEditor(weeklyDraft.text,weeklyDraft.startDate,weeklyDraft.repeat);return;}
  if(a==='week-day'){selected=id;render();return;}
  if(a==='week-prev'||a==='week-next'){selected=offsetDate(selected,a==='week-prev'?-7:7);render();return;}
  if(a==='week-today'){selected=dateKey();render();return;}
  if(a==='prev'||a==='next'){selected=offsetDate(selected,a==='prev'?-1:1);render();return;}
  if(a==='go-training'||a==='go-food'){location.hash=a==='go-food'?'food':'training';return;}
  if(a==='quick-weight'){const recordDate=selected,weight=ensureDay(state,recordDate).weight;modal('记录体重',`<p class="muted">记录到 ${esc(recordDate)}。尽量在相似条件下测量，未称重时可以留空。</p><label for="quickWeight">体重（kg）</label><input id="quickWeight" name="weight" type="number" min="1" max="500" step="0.1" value="${weight??''}"><button class="secondary wide actions" type="button" data-action="go-weight-trends">查看体重趋势</button>`,f=>{ensureDay(state,recordDate).weight=num(f,'weight');});return;}
  if(a==='go-weight-trends'){closeModal();location.hash='trends';return;}
  if(a==='weight-range'){weightRange=Number(id)===30?30:7;render();return;}
  if(a==='go-settings'){location.hash='settings';return;}
  if(a==='voice-meal'){requestSpeech();return;}
  if(a==='meal-text'){speechEditor();return;}
  if(a==='edit-speech'){speechEditor(speechDraft.text,speechDraft.noteId,speechDraft.date);return;}
  if(a==='save-food-note'){storeFoodNote();return;}
  if(a==='resolve-food-note'){const note=day.foodNotes.find(n=>n.id===id);if(note)speechEditor(note.text,note.id,selected);return;}
  if(a==='delete-food-note'){if(!confirm('删除这条尚未计算热量的饮食备注？'))return;day.foodNotes=day.foodNotes.filter(n=>n.id!==id);}
  if(a==='repeat-meal'){const entry=recentMeals(state)[Number(id)];if(!entry)return;repeatMeal(day,entry,uid());if(save())toast('已沿用上次份量记录');render();return;}
  if(a==='quick-food'){const food=state.foods.find(f=>f.id===id);if(!food)return;addMeal(day,food,food.portionGrams??100,inferredMeal());if(save())toast(`已记录 ${food.name} ${food.portionGrams??100}g`);render();return;}
  if(a==='copy-yesterday'){const previous=state.days[offsetDate(selected,-1)];if(!previous?.meals.length)return;if(!confirm(`把昨天 ${previous.meals.length} 条饮食复制到今天？仅当吃法和份量相同时使用。`))return;for(const m of previous.meals)day.meals.push({...cloneData(m),id:uid()});day.foodComplete=false;}
  if(a==='apply-plan'){const plan=state.plans.find(p=>p.id===id);if(!plan)return;if(day.tasks.some(t=>t.planId===plan.id)){toast('今天已经有这个计划');return;}day.tasks.push({...cloneData(plan),id:uid(),planId:plan.id,status:'pending',sets:[],actualMinutes:null});}
  if(a==='add-task'){taskForm();return;}if(a==='add-plan'||a==='edit-plan'){taskForm(true,state.plans.find(p=>p.id===id));return;}
  if(a==='add-food'||a==='edit-food'){foodForm(state.foods.find(f=>f.id===id));return;}
  if(a==='toggle'&&t&&selected>dateKey()){toast('未来安排可查看和调整，请到当天再打卡');return;}
  if(a==='toggle'&&t){t.status=t.status==='done'?'pending':'done';delete t.reason;}
  if(a==='delete-task'&&t){if(!confirm(`删除“${t.name}”及它的组数记录？`))return;day.tasks=day.tasks.filter(x=>x.id!==id);}
  if(a==='delete-plan'){if(!confirm('删除重复计划？历史和已生成的当天安排会保留。'))return;state.plans=state.plans.filter(x=>x.id!==id);}
  if(a==='skip'&&t){if(t.status==='skipped'){t.status='pending';delete t.reason;}else{modal('记录跳过原因','<label for="reason">原因</label><input id="reason" name="reason" required maxlength="300" placeholder="例如：临时有事、身体疲劳">',f=>{if(!f.get('reason').trim())throw Error('请填写原因');t.status='skipped';t.reason=f.get('reason').trim();});return;}}
  if(a==='sets'&&t){modal(`${t.name} · 训练详情`,`<label for="actualMinutes">实际时长（分钟）</label><input id="actualMinutes" name="actualMinutes" type="number" min="0" max="1440" step="0.1" value="${t.actualMinutes??''}"><label for="sets">逐组记录：每行填写 重量kg,次数</label><textarea id="sets" name="sets" maxlength="5000" placeholder="20,12&#10;20,10">${t.sets.map(s=>`${s.weight},${s.reps}`).join('\n')}</textarea><small>自重动作可以填 0 kg；有氧运动可以只填时长。</small>`,f=>{const lines=f.get('sets').trim();const sets=lines?lines.split('\n').map(l=>{const vals=l.trim().split(/[,，\s]+/);const weight=Number(vals[0]),reps=Number(vals[1]);if(vals.length!==2||!Number.isFinite(weight)||weight<0||weight>2000||!Number.isInteger(reps)||reps<1||reps>10000)throw Error('每行填写有效的重量和整数次数，例如 20,12');return {weight,reps};}):[];t.sets=sets;t.actualMinutes=num(f,'actualMinutes');});return;}
  if(a==='add-meal'){if(!state.foods.length){toast('先创建一种常吃的食物，再记录份量');foodForm();return;}modal('记录饮食',`<label for="foodId">选择食物</label><select id="foodId" name="foodId">${state.foods.map(f=>`<option value="${esc(f.id)}">${esc(f.name)}</option>`).join('')}</select><label for="grams">这次吃了多少（g）</label><input id="grams" name="grams" type="number" min="0.1" max="10000" step="0.1" required><label for="meal">餐次</label><select id="meal" name="meal"><option>早餐</option><option>午餐</option><option>晚餐</option><option>加餐</option></select>`,f=>addMeal(day,state.foods.find(x=>x.id===f.get('foodId')),num(f,'grams'),f.get('meal')));return;}
  if(a==='delete-meal'){if(!confirm('删除这条饮食记录？'))return;day.meals=day.meals.filter(m=>m.id!==id);day.foodComplete=false;}
  if(a==='food-complete'){if(day.foodNotes.length){toast('还有待补全的饮食备注，请先补录或删除');return;}if(!day.foodComplete&&!day.meals.length){toast('请先记录饮食');return;}day.foodComplete=!day.foodComplete;}
  if(a==='recovery'){const current=recoveryFor(state,selected);modal('手动记录身体状态',`<p class="muted">可记录自己的睡眠与身体状态；没有数据的项目可以留空。</p><label for="score">恢复分数（%，可留空）</label><input id="score" name="score" type="number" min="0" max="100" step="0.1" value="${current?.score??''}"><label for="sleepHours">睡眠时长（小时，可留空）</label><input id="sleepHours" name="sleepHours" type="number" min="0" max="48" step="0.1" value="${current?.sleepHours??''}">`,f=>{const score=num(f,'score'),sleepHours=num(f,'sleepHours');day.recovery=score===null&&sleepHours===null?null:{score,sleepHours,source:'manual'};});return;}
  if(a==='rest'){restEnd=Date.now()+Number(button.dataset.seconds)*1000;tick();return;}if(a==='stop-rest'){restEnd=0;tick();return;}
  if(a==='notification'){if(native)native.requestNotifications();else toast('系统提醒需要安装安卓版本');return;}
  if(a==='test-reminder'){const result=nativeStatus('testReminder',{ok:false,message:'浏览器无法发送手机通知，请在安装版中测试提醒。'});testReminderFeedback=result.message||'无法读取测试结果，请检查通知设置';if($('#test-reminder-feedback'))$('#test-reminder-feedback').textContent=testReminderFeedback;toast(testReminderFeedback);refreshNativeStatus();return;}
  if(a==='exact-alarms'){if(native?.requestExactAlarms)native.requestExactAlarms();else toast('精准提醒授权需要手机安装版');return;}
  if(a==='notification-settings'){if(native?.openNotificationSettings)native.openNotificationSettings();else toast('声音、振动与后台设置需要手机安装版');return;}
  if(a==='health-permissions'){if(native?.requestHealthPermissions)native.requestHealthPermissions();else toast('需要支持该系统服务的手机安装版；Mate60Pro优先使用云连接');return;}
  if(a==='health-sync'){await syncHealth();return;}
  if(a==='export'){const raw=storageBroken?(native?native.read():localStorage.getItem('daily-motion-v1')):JSON.stringify(state,null,2);if(native)native.exportBackup(raw??'');else{const url=URL.createObjectURL(new Blob([raw??''],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`daily-motion-${dateKey()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}return;}
  if(a==='import'){if(native)native.importBackup();else $('#import-file').click();return;}
  if(a==='whoop-sync'){await syncWhoop();return;}
  if(a==='whoop-check'){await checkWhoop();return;}
  if(a==='whoop-auth'){if(formDrafts.has('connection-form')){toast('连接信息有未保存修改，请先保存连接');return;}try{const {url}=await api('/api/authorize','POST');if(!url.startsWith('https://api.prod.whoop.com/'))throw Error('授权地址无效');if(native)native.openBrowser(url);else window.open(url,'_blank','noopener');}catch(e){toast(e.message);}return;}
  if(a==='whoop-disconnect'){
    if(!confirm('撤销服务端 WHOOP 授权，并清除本机同步缓存？手动记录会保留。'))return;const revision=connectionRevision;
    try{await api('/api/disconnect','POST');if(revision!==connectionRevision){toast('原连接已撤销，当前新连接保留');return;}state.whoop={records:[],syncedAt:null};state.settings.serverUrl='';const persisted=save();if(native)native.setPairToken('');else sessionStorage.removeItem('motion-pair-token');formDrafts.delete('connection-form');connectionRevision++;whoopStatus=null;whoopSyncError=null;if(persisted)toast('已断开并清除缓存');render();return;}catch(e){toast(e.message);return;}
  }
  save();render();
}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-tab]');if(nav){location.hash=nav.dataset.tab;return;}const b=e.target.closest('[data-action]');if(b)action(b.dataset.action,b.dataset.id,b).catch(e=>toast(e.message));});
$('#close-dialog').onclick=()=>closeModal();
document.addEventListener('change',e=>{if(e.target.id==='carbMode'){updateCarbSettingsVisibility();return;}if(e.target.id==='carb-day-type'){const value=e.target.value;if(!['auto','training','rest'].includes(value))return;ensureDay(state,selected).carbDayType=value;save();render();return;}if(e.target.id==='day'&&/^\d{4}-\d{2}-\d{2}$/.test(e.target.value)&&(tab==='training'||e.target.value<=dateKey())){selected=e.target.value;render();}});
document.addEventListener('submit',e=>{
  const form=e.target;if(!editableFormIds.has(form.id))return;e.preventDefault();const f=new FormData(form);let connectionChange=null;
  if(form.id==='settings-form'){
    if(f.has('reminders')&&[f.get('trainingTime'),f.get('mealTime')].some(t=>isQuietTime(t,f.get('quietStart')||'22:30',f.get('quietEnd')||'07:00'))){toast('训练和饮食检查时间需要在夜间静默时段之外');return;}
    Object.assign(state.settings,{goal:f.get('goal'),calories:num(f,'calories'),protein:num(f,'protein'),carbMode:f.get('carbMode')||'fixed',carbs:f.get('carbMode')==='cycle'?state.settings.carbs:num(f,'carbs'),trainingCarbs:f.get('carbMode')==='cycle'?num(f,'trainingCarbs'):state.settings.trainingCarbs,restCarbs:f.get('carbMode')==='cycle'?num(f,'restCarbs'):state.settings.restCarbs,reminders:f.has('reminders'),trainingTime:f.get('trainingTime'),mealTime:f.get('mealTime'),reminderMaxCount:num(f,'reminderMaxCount')??3,reminderIntervalMinutes:num(f,'reminderIntervalMinutes')??30,quietStart:f.get('quietStart')||'22:30',quietEnd:f.get('quietEnd')||'07:00'});
  }
  if(form.id==='journal-form')Object.assign(ensureDay(state,form.dataset.recordDate||selected),{weight:num(f,'weight'),note:f.get('note')});
  if(form.id==='connection-form'){
    const url=f.get('serverUrl').trim().replace(/\/$/,'');
    try{if(url){const u=new URL(url);if(u.protocol!=='https:'||u.username||u.password||u.pathname!=='/'||u.search||u.hash)throw Error();}}catch{toast('请填写 HTTPS 服务根地址，例如 https://example.com');return;}
    const token=f.get('pairToken').trim(),urlChanged=url!==state.settings.serverUrl;connectionChange={token,urlChanged,changed:urlChanged||!!token};
    if(connectionChange.changed)state.whoop={records:[],syncedAt:null};state.settings.serverUrl=url;
  }
  if(save()){
    if(connectionChange?.changed){if(connectionChange.urlChanged){if(native)native.setPairToken('');else sessionStorage.removeItem('motion-pair-token');}if(connectionChange.token){if(native)native.setPairToken(connectionChange.token);else sessionStorage.setItem('motion-pair-token',connectionChange.token);}connectionRevision++;whoopStatus=null;whoopSyncError=null;}
    clearFormDraft(form);toast('已保存');if(form.id==='settings-form'&&native&&state.settings.reminders)native.requestNotifications();
  }
  render();
});
function restore(raw){try{if(raw.length>5_000_000)throw Error('备份文件过大');const data=validateState(JSON.parse(raw));if(!confirm('恢复将替换当前本机全部记录，建议先导出备份。继续恢复？'))return;const old=state,oldBroken=storageBroken;data.settings.serverUrl='';state=data;storageBroken=false;if(!save()){state=old;storageBroken=oldBroken;return;}if(native)native.setPairToken('');else sessionStorage.removeItem('motion-pair-token');formDrafts.clear();connectionRevision++;whoopStatus=null;whoopSyncError=null;healthSyncError=null;render();toast('备份已恢复。外部连接需重新配置，连接密钥未从备份恢复。');}catch(e){toast(e.message);}}
globalThis.restoreBackup=restore;
document.addEventListener('submit',e=>{
  if(e.target.id==='speech-text-form'){e.preventDefault();speechReview(new FormData(e.target).get('text').trim());}
  if(e.target.id==='speech-review-form'){
    e.preventDefault();const f=new FormData(e.target),draft=speechDraft,parsed=draft.parsed;
    if(!parsed||!parsed.items.length||parsed.unmatched){toast('还有未匹配食物，请先补全常吃食物资料');return;}
    const entries=parsed.items.map((item,i)=>({food:state.foods.find(x=>x.id===item.foodId),grams:Number(f.get(`grams-${i}`))}));
    if(entries.some(x=>!x.food||!Number.isFinite(x.grams)||x.grams<=0||x.grams>10000)){toast('请确认每项食物和有效克数');return;}
    const day=ensureDay(state,draft.date);entries.forEach(x=>addMeal(day,x.food,x.grams,f.get('meal')));if(draft.noteId)day.foodNotes=day.foodNotes.filter(n=>n.id!==draft.noteId);
    if(save())toast(`已记录 ${entries.length} 项饮食`);closeModal();render();
  }
});
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(file){if(file.size>5_000_000)toast('备份文件过大');else restore(await file.text());}e.target.value='';};
globalThis.nativeStatusUpdated=()=>refreshNativeStatus();
window.addEventListener('hashchange',()=>{tab=location.hash.slice(1);render();window.scrollTo({top:0});});
function tick(){const el=$('#timer');if(!el)return;if(restEnd){const s=Math.max(0,Math.ceil((restEnd-Date.now())/1000));el.textContent=s?`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`:'休息结束，准备下一组';}else el.textContent='准备好了再开始';}
setInterval(tick,1000);
let activeDate=dateKey();setInterval(()=>{const now=dateKey();if(now!==activeDate){if(selected===activeDate)selected=now;activeDate=now;render();save();}},30000);
setInterval(()=>{if(SYNC_ENABLED&&!document.hidden&&state.settings.serverUrl)syncWhoop(true);},15*60*1000);
render();if(!storageBroken)save();if(SYNC_ENABLED&&state.settings.serverUrl)syncWhoop(true);
